use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicUsize,Ordering};use ingetrazo_core::mesh::Mesh;use glam::DVec3;
static FAIL:AtomicUsize=AtomicUsize::new(0);struct Fault;unsafe impl GlobalAlloc for Fault{unsafe fn alloc(&self,l:Layout)->*mut u8{if FAIL.fetch_update(Ordering::SeqCst,Ordering::SeqCst,|n|if n>0{Some(n-1)}else{None}).ok()==Some(1){std::ptr::null_mut()}else{System.alloc(l)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{if FAIL.fetch_update(Ordering::SeqCst,Ordering::SeqCst,|n|if n>0{Some(n-1)}else{None}).ok()==Some(1){std::ptr::null_mut()}else{System.realloc(p,l,n)}}}#[global_allocator]static ALLOC:Fault=Fault;
fn main(){let mut refused=0;for edges in [true,false]{for fail in 1..=2{let mut m=Mesh::new();m.add_vertex(DVec3::ZERO);m.add_vertex(DVec3::X);m.add_edge(0,1);let budget=owner_budget::OwnerBudget::new(None);let mut o=owner::JournalOwner::new_with_budget(m,budget.clone()).unwrap();let mut t=o.try_begin().unwrap();t.add_edge(DVec3::X,DVec3::Y).unwrap();o.commit(t).unwrap();o.undo().unwrap();let before=o.mesh().clone();let history=o.history_counts();assert_eq!(history,(0,1));let state=o.state_token();let charge=budget.snapshot().total();let mut candidate=before.clone();if !edges{candidate.edges.clear();for v in &mut candidate.vertices{v.edges.clear();}}let target=uuid::Uuid::new_v4();FAIL.store(fail,Ordering::SeqCst);let result=o.prepare_packed_replacement_as(candidate,target);assert!(result.is_err());drop(result);assert_eq!(FAIL.load(Ordering::SeqCst),0);assert_eq!(o.mesh(),&before);assert_eq!(o.history_counts(),history);assert_eq!(o.state_token(),state);assert_eq!(budget.snapshot().total(),charge);assert!(o.redo().unwrap());refused+=1;drop(o);assert_eq!(budget.snapshot().total(),0);}}println!("{}",serde_json::json!({"actual_native_allocation_refusals":refused,"preexisting_redo_preserved":true,"graph_state_and_charge_preserved":true,"bigint_and_vm_heap_failure_included":false,"production_enabled":false}));}
